{"command": "df -h /tmp | tail -1; mkdir -p /tmp/tools && cd /tmp/tools && cat > mkfiles.c <<'EOF'
#include <stdio.h>
#include <fcntl.h>
#include <string.h>
#include <stdlib.h>
int main(int argc, char** argv){
  // argv[1]=prefix, argv[2]=charset, argv[3]=length
  const char*pre = argv[1]; const char*cs = argv[2]; int L = atoi(argv[3]);
  int n = strlen(cs); long total = 1; for(int i=0;i<L;i++) total*=n;
  char buf[512];
  for(long x=0;x<total;x++){
    long y=x; int idx[16]; for(int i=0;i<L;i++){ idx[i]=y%n; y/=n; }
    int p = snprintf(buf,sizeof buf,"%s",pre);
    for(int i=L-1;i>=0;i--) buf[p++]=cs[idx[i]];
    buf[p]=0;
    int fd = open(buf, O_CREAT|O_WRONLY|O_TRUNC, 0644); if(fd>=0) close(fd);
  }
  return 0;
}
EOF
gcc -O2 -o mkfiles mkfiles.c && echo built"}

