EOF
cat > src/lib.rs <<'EOF'
//! Minimal stand-in for the `terminal_size` crate.
//!
//! Provides the `terminal_size()` function that `clap`'s `wrap_help` feature uses in order
//! to determine the width of the output stream.

use libc::{ioctl, winsize, STDOUT_FILENO, TIOCGWINSZ};

/// The width of a terminal in columns.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Width(pub u16);

/// The height of a terminal in rows.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Height(pub u16);

/// Query the size of the terminal attached to stdout.
pub fn terminal_size() -> Option<(Width, Height)> {
    terminal_size_of(STDOUT_FILENO)
}

fn terminal_size_of(fd: libc::c_int) -> Option<(Width, Height)> {
    unsafe {
        let mut ws: winsize = std::mem::zeroed();
        if ioctl(fd, TIOCGWINSZ, &mut ws) == -1 || ws.ws_col == 0 {
            None
        } else {
            Some((Width(ws.ws_col), Height(ws.ws_row)))
        }
    }
}
EOF
