//! Small path helpers shared by the rest of the program.

use std::path::{Path, PathBuf};

/// Strip leading `.` components from a path (the ones that would end up right after the
/// current directory when making the path absolute).
pub fn strip_leading_cur_dir(path: &Path) -> &Path {
    let mut p = path;
    loop {
        match p.strip_prefix(".") {
            Ok(rest) if !rest.as_os_str().is_empty() => p = rest,
            _ => return p,
        }
    }
}

/// Make `path` absolute with respect to `cwd`, without resolving symlinks.
pub fn to_absolute(cwd: &Path, path: &Path) -> PathBuf {
    if path.is_absolute() {
        return path.to_path_buf();
    }
    cwd.join(strip_leading_cur_dir(path))
}

/// Returns the "extension" of the file name, i.e. the part after the last `.` of the
/// last path component, without the leading dot. Returns `None` when the file name has
/// no extension.
pub fn extension(file_name: &str) -> Option<&str> {
    // Mirrors std's `Path::extension` semantics.
    let bytes = file_name.as_bytes();
    if bytes.is_empty() {
        return None;
    }
    let idx = match file_name.rfind('.') {
        Some(i) => i,
        None => return None,
    };
    // A leading dot does not count as an extension separator (".foo" has no extension).
    if idx == 0 {
        return None;
    }
    Some(&file_name[idx + 1..])
}

/// Percent-encode a path so that it can be used inside a `file://` URL.
pub fn url_encode(path: &Path) -> String {
    let mut out = String::new();
    let s = path.to_string_lossy();
    for (i, comp) in s.split('/') {
        if i > 0 {
            out.push('/');
        }
        for b in comp.bytes() {
            if is_unreserved(b) {
                out.push(b as char);
            } else {
                out.push_str(&format!("%{:02X}", b));
            }
        }
    }
    out
}

fn is_unreserved(b: u8) -> bool {
    b.is_ascii_alphanumeric() || matches!(b, b'-' | b'.' | b'_' | b'~')
}

/// Returns the hostname of the current machine (used for `file://` hyperlinks).
pub fn hostname() -> String {
    let mut buf = [0u8; 256];
    let res = unsafe {
        libc::gethostname(buf.as_mut_ptr() as *mut libc::c_char, buf.len())
    };
    if res == 0 {
        let len = buf.iter().position(|&b| b == 0).unwrap_or(buf.len());
        String::from_utf8_lossy(&buf[..len]).to_string()
    } else {
        String::new()
    }
}
RSEOF
