//! The file filters: size, modification time and owner.

use std::time::{Duration, SystemTime, UNIX_EPOCH};

// ---------------------------------------------------------------------------
// Size
// ---------------------------------------------------------------------------

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum SizeOp {
    GreaterThanOrEqual,
    LessThanOrEqual,
    Equal,
}

#[derive(Clone, Copy, Debug)]
pub struct SizeFilter {
    pub op: SizeOp,
    pub size: u64,
}

impl SizeFilter {
    pub fn matches(&self, size: u64) -> bool {
        match self.op {
            SizeOp::GreaterThanOrEqual => size >= self.size,
            SizeOp::LessThanOrEqual => size <= self.size,
            SizeOp::Equal => size == self.size,
        }
    }
}

/// Parse a size constraint in the form `[+|-]<NUM><UNIT>`.
pub fn parse_size(s: &str) -> Option<SizeFilter> {
    let mut rest = s;
    let op = if let Some(r) = rest.strip_prefix('+') {
        rest = r;
        SizeOp::GreaterThanOrEqual
    } else if let Some(r) = rest.strip_prefix('-') {
