fn unit_rank(name: &str) -> i32 {
    match name {
        "years" | "year" | "yrs" | "yr" | "y" => 0,
        "months" | "month" | "mo" => 1,
        "weeks" | "week" | "wks" | "wk" | "w" => 2,
        "days" | "day" | "d" => 3,
        "hours" | "hour" | "hrs" | "hr" | "h" => 4,
        "minutes" | "minute" | "mins" | "min" | "m" => 5,
        "seconds" | "second" | "secs" | "sec" | "s" => 6,
        _ => 7,
    }
}

fn sub_second_multiplier(name: &str) -> (u64, ()) {
    match name {
        "milliseconds" | "millisecond" | "ms" => (1_000_000, ()),
        "microseconds" | "microsecond" | "us" => (1_000, ()),
        _ => (1, ()),
    }
}

/// Parse a `YYYY-MM-DD[ HH:MM:SS]` date in the local time zone.
fn parse_datetime(s: &str) -> Option<SystemTime> {
    use chrono::{NaiveDate, NaiveDateTime, NaiveTime, Local};
    let s = s.trim();
    let parts: Vec<&str> = s.splitn(2, ' ').collect();
    let date = NaiveDate::parse_from_str(parts[0], "%Y-%m-%d").ok()?;
    let time = if parts.len() > 1 {
        NaiveTime::parse_from_str(parts[1], "%H:%M:%S").ok()?
    } else {
        NaiveTime::from_hms_opt(0, 0, 0)?
    };
    let naive = NaiveDateTime::new(date, time);
    let local = Local.from_local_datetime(&naive).single()?;
    Some(local.into())
}

// ---------------------------------------------------------------------------
// Owner
// ---------------------------------------------------------------------------

#[derive(Clone, Debug)]
pub struct OwnerFilter {
    pub user: Option<u32>,
    pub user_negated: bool,
    pub group: Option<u32>,
    pub group_negated: bool,
}

impl OwnerFilter {
    pub fn matches(&self, uid: u32, gid: u32) -> bool {
        let mut user_ok = true;
        if let Some(u) = self.user {
            user_ok = if self.user_negated { uid != u } else { uid == u };
        }
        let mut group_ok = true;
        if let Some(g) = self.group {
            group_ok = if self.group_negated { gid != g } else { gid == g };
        }
        user_ok && group_ok
    }
}

/// Parse an owner filter of the form `[(user|uid)][:(group|gid)]` with an optional `!`
/// negation in front of either side.
pub fn parse_owner(s: &str) -> Result<OwnerFilter, String> {
    let (user_str, group_str) = match s.split_once(':') {
        Some((u, g)) => (Some(u), Some(g)),
        None => (Some(s), None),
    };
    if s.matches(':').count() > 1 {
        return Err(format!(
            "more than one ':' present in owner string '{}'. See 'fd --help'.",
            s
        ));
    }
    let (user_negated, user) = parse_owner_part(user_str, true)?;
    let (group_negated, group) = parse_owner_part(group_str, false)?;
    Ok(OwnerFilter { user, user_negated, group, group_negated })
}

fn parse_owner_part(
    part: Option<&str>,
    is_user: bool,
) -> Result<(bool, Option<u32>), String> {
    let part = match part {
        None => return Ok((false, None)),
        Some(p) => p,
    };
    let kind = if is_user { "user" } else { "group" };
    let (negated, rest) = match part.strip_prefix('!') {
        Some(r) => (true, r),
        None => (false, part),
    };
    if rest.is_empty() {
        if negated {
            return Err(format!("'' is not a recognized {} name", kind));
        }
        return Ok((false, None));
    }
    let id = resolve_id(rest, kind)?;
    Ok((negated, Some(id)))
}

fn resolve_id(s: &str, kind: &str) -> Result<u32, String> {
    // Try to parse it as a numeric id first.
    if let Ok(id) = s.parse::<u32>() {
        let (valid, _) = lookup_id(id, kind == "user");
        if valid {
            return Ok(id);
        }
    }
    match lookup_name(s, kind == "user") {
        Some(id) => Ok(id),
        None => Err(format!("'{}' is not a recognized {} name", s, kind)),
    }
}

fn lookup_name(name: &str, user: bool) -> Option<u32> {
    if user {
        unsafe {
            let mut pwd: *mut libc::passwd = std::ptr::null_mut();
            let mut buf = vec![0u8; 4096];
            let mut result: *mut libc::passwd = std::ptr::null_mut();
            let c_name = std::ffi::CString::new(name).ok()?;
            let res = libc::getpwnam_r(
                c_name.as_ptr(),
                pwd.as_mut(),
                buf.as_mut_ptr() as *mut libc::c_char,
                buf.len(),
                &mut result,
            );
            if res == 0 && !result.is_null() {
                return Some((*result).pw_uid as u32);
            }
            None
        }
    } else {
        unsafe {
            let mut grp: *mut libc::group = std::ptr::null_mut();
            let mut buf = vec![0u8; 4096];
            let mut result: *mut libc::group = std::ptr::null_mut();
            let c_name = std::ffi::CString::new(name).ok()?;
            let res = libc::getgrnam_r(
                c_name.as_ptr(),
                grp.as_mut(),
                buf.as_mut_ptr() as *mut libc::c_char,
                buf.len(),
                &mut result,
            );
            if res == 0 && !result.is_null() {
                return Some((*result).gr_gid as u32);
            }
            None
        }
    }
}

fn lookup_id(id: u32, user: bool) -> (bool, Option<String>) {
    unsafe {
        if user {
            let mut pwd: *mut libc::passwd = std::ptr::null_mut();
            let mut buf = vec![0u8; 4096];
            let mut result: *mut libc::passwd = std::ptr::null_mut();
            let res = libc::getpwuid_r(
                id as libc::uid_t,
                pwd.as_mut(),
                buf.as_mut_ptr() as *mut libc::c_char,
                buf.len(),
                &mut result,
            );
            if res == 0 && !result.is_null() {
                let name = std::ffi::CStr::from_ptr((*result).pw_name)
                    .to_string_lossy()
                    .to_string();
                (true, Some(name))
            } else {
                (false, None)
            }
        } else {
            let mut grp: *mut libc::group = std::ptr::null_mut();
            let mut buf = vec![0u8; 4096];
            let mut result: *mut libc::group = std::ptr::null_mut();
            let res = libc::getgrgid_r(
                id as libc::gid_t,
                grp.as_mut(),
                buf.as_mut_ptr() as *mut libc::c_char,
                buf.len(),
                &mut result,
            );
            if res == 0 && !result.is_null() {
                let name = std::ffi::CStr::from_ptr((*result).gr_name)
                    .to_string_lossy()
                    .to_string();
                (true, Some(name))
            } else {
                (false, None)
            }
        }
    }
}
RSEOF
echo ok"}

