//! The file filters: size, modification time and owner.

use std::time::{Duration, SystemTime, UNIX_EPOCH};

// ---------------------------------------------------------------------------
// Size
// ---------------------------------------------------------------------------

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum SizeOp {
    GreaterThanOrEqual,
    LessThanOrEqual,
    Equal,
}

#[derive(Clone, Copy, Debug)]
pub struct SizeFilter {
    pub op: SizeOp,
    pub size: u64,
}

impl SizeFilter {
    pub fn matches(&self, size: u64) -> bool {
        match self.op {
            SizeOp::GreaterThanOrEqual => size >= self.size,
            SizeOp::LessThanOrEqual => size <= self.size,
            SizeOp::Equal => size == self.size,
        }
    }
}

/// Parse a size constraint in the form `[+|-]<NUM><UNIT>`.
pub fn parse_size(s: &str) -> Option<SizeFilter> {
    let mut rest = s;
    let op = if let Some(r) = rest.strip_prefix('+') {
        rest = r;
        SizeOp::GreaterThanOrEqual
    } else if let Some(r) = rest.strip_prefix('-') {
        rest = r;
        SizeOp::LessThanOrEqual
    } else {
        SizeOp::Equal
    };

    let digits_end = rest.find(|c: char| !c.is_ascii_digit()).unwrap_or(rest.len());
    if digits_end == 0 {
        return None;
    }
    let num: u64 = rest[..digits_end].parse().ok()?;
    let unit = &rest[digits_end..];
    if unit.is_empty() {
        return None;
    }
    let mult = unit_multiplier(&unit.to_ascii_lowercase())?;
    Some(SizeFilter { op, size: num.checked_mul(mult)? })
}

fn unit_multiplier(unit: &str) -> Option<u64> {
    // The unit is an optional base letter (k/m/g/t) followed by an optional 'i' and an
    // optional 'b'.
    match unit {
        "b" => Some(1),
        "k" | "kb" => Some(1_000),
        "ki" | "kib" => Some(1_024),
        "m" | "mb" => Some(1_000_000),
        "mi" | "mib" => Some(1_048_576),
        "g" | "gb" => Some(1_000_000_000),
        "gi" | "gib" => Some(1_073_741_824),
        "t" | "tb" => Some(1_000_000_000_000),
        "ti" | "tib" => Some(1_099_511_627_776),
        _ => None,
    }
}

// ---------------------------------------------------------------------------
// Time
// ---------------------------------------------------------------------------

#[derive(Clone, Copy, Debug)]
pub struct TimeFilter {
    pub before: bool,
    pub time: SystemTime,
}

impl TimeFilter {
    pub fn matches(&self, mtime: SystemTime) -> bool {
        if self.before {
            mtime < self.time
        } else {
            mtime > self.time
        }
    }
}

/// Parse a date or duration string as accepted by `--changed-within`/`--changed-before`.
pub fn parse_time(s: &str) -> Option<TimeFilter> {
    if let Some(stripped) = s.strip_prefix('@') {
        let secs: i64 = stripped.parse().ok()?;
        return Some(TimeFilter {
            before: false,
            time: UNIX_EPOCH + Duration::from_secs(secs.max(0) as u64),
        });
    }
    if let Some(dur) = parse_duration(s) {
        let now = SystemTime::now();
        return Some(TimeFilter {
            before: false,
            time: now.checked_sub(dur).unwrap_or(UNIX_EPOCH),
        });
    }
    if let Some(dt) = parse_datetime(s) {
        return Some(TimeFilter { before: false, time: dt });
    }
    None
}

/// Parse a duration expression like `2weeks`, `1h30m`, `1 d 1 h`.
pub fn parse_duration(s: &str) -> Option<Duration> {
    // The components must appear in decreasing order of magnitude and each unit may only
    // occur once. Optional whitespace is allowed between the number and the unit and
    // between the components.
    const UNITS: &[(&str, u64)] = &[
        ("years", 365 * 24 * 3600),
        ("year", 365 * 24 * 3600),
        ("yrs", 365 * 24 * 3600),
        ("yr", 365 * 24 * 3600),
        ("y", 365 * 24 * 3600),
        ("months", 31 * 24 * 3600),
        ("month", 31 * 24 * 3600),
        ("mo", 31 * 24 * 3600),
        ("weeks", 7 * 24 * 3600),
        ("week", 7 * 24 * 3600),
        ("wks", 7 * 24 * 3600),
        ("wk", 7 * 24 * 3600),
        ("w", 7 * 24 * 3600),
        ("days", 24 * 3600),
        ("day", 24 * 3600),
        ("d", 24 * 3600),
        ("hours", 3600),
        ("hour", 3600),
        ("hrs", 3600),
        ("hr", 3600),
        ("h", 3600),
        ("minutes", 60),
        ("minute", 60),
        ("mins", 60),
        ("min", 60),
        ("m", 60),
        ("seconds", 1),
        ("second", 1),
        ("secs", 1),
        ("sec", 1),
        ("s", 1),
        ("milliseconds", 0),
        ("millisecond", 0),
        ("ms", 0),
        ("microseconds", 0),
        ("microsecond", 0),
        ("us", 0),
        ("nanoseconds", 0),
        ("nanosecond", 0),
        ("nsecs", 0),
        ("nsec", 0),
        ("ns", 0),
    ];

    let mut seconds: u64 = 0;
    let mut nanos: u64 = 0;
    let mut idx = 0usize;
    let bytes = s.as_bytes();
    let mut last_unit_rank: i32 = -1;
    let mut matched_any = false;

    while idx < bytes.len() {
        // Skip optional whitespace between components.
        while idx < bytes.len() && bytes[idx] == b' ' {
            idx += 1;
        }
        if idx >= bytes.len() {
            break;
        }
        // Parse the number.
        let start = idx;
        while idx < bytes.len() && bytes[idx].is_ascii_digit() {
            idx += 1;
        }
        if start == idx {
            return None;
        }
        let num: u64 = s[start..idx].parse().ok()?;
        // Optional whitespace between number and unit.
        while idx < bytes.len() && bytes[idx] == b' ' {
            idx += 1;
        }
        // Parse the unit.
        let mut found = None;
        for (name, secs) in UNITS {
            if s[idx..].starts_with(name) {
                found = Some((*name, *secs));
                break;
            }
        }
        let (name, unit_secs) = found?;
        idx += name.len();
        // The units must be in decreasing order of magnitude.
        let rank = unit_rank(name);
        if rank <= last_unit_rank {
            return None;
        }
        last_unit_rank = rank;
        if unit_secs == 0 {
            // Sub-second units.
            let (mult, _) = sub_second_multiplier(name);
            nanos = nanos.saturating_add(num.saturating_mul(mult));
        } else {
            seconds = seconds.checked_add(num.checked_mul(unit_secs)?)?;
        }
        matched_any = true;
    }
    if !matched_any {
        return None;
    }
    Some(Duration::new(seconds, nanos.min(999_999_999) as u32))
}

fn unit_rank(name: &str) -> i32 {
    match name {
        "years" | "year" | "yrs" | "yr" | "y" => 0,
        "months" | "month" | "mo" => 1,
        "weeks" | "week" | "wks" | "wk" | "w" => 2,
        "days" | "day" | "d" => 3,
        "hours" | "hour" | "hrs" | "hr" | "h" => 4,
        "minutes" | "minute" | "mins" | "min" | "m" => 5,
        "seconds" | "second" | "secs" | "sec" | "s" => 6,
        _ => 7,
    }
}

fn sub_second_multiplier(name: &str) -> (u64, ()) {
    match name {
        "milliseconds" | "millisecond" | "ms" => (1_000_000, ()),
        "microseconds" | "microsecond" | "us" => (1_000, ()),
        _ => (1, ()),
    }
}

/// Parse a `YYYY-MM-DD[ HH:MM:SS]` date in the local time zone.
fn parse_datetime(s: &str) -> Option<SystemTime> {
    use chrono::{NaiveDate, NaiveDateTime, NaiveTime, Local};
    let s = s.trim();
    let parts: Vec<&str> = s.splitn(2, ' ').collect();
    let date = NaiveDate::parse_from_str(parts[0], "%Y-%m-%d").ok()?;
    let time = if parts.len() > 1 {
        NaiveTime::parse_from_str(parts[1], "%H:%M:%S").ok()?
    } else {
        NaiveTime::from_hms_opt(0, 0, 0)?
    };
    let naive = NaiveDateTime::new(date, time);
    let local = Local.from_local_datetime(&naive).single()?;
    Some(local.into())
}

