//! Command line configuration.

use crate::cli::Cli;
use crate::error::FdError;
use crate::filters::{parse_owner, parse_size, parse_time, OwnerFilter, SizeFilter, TimeFilter};
use crate::lscolors::{default_ls_colors, Indicator, LsColors, Style};
use globset::{GlobBuilder, GlobMatcher};
use regex::RegexBuilder;
use std::ffi::OsString;
use std::path::{Path, PathBuf};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ColorMode {
    Auto,
    Always,
    Never,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum HyperlinkMode {
    Auto,
    Always,
    Never,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum StripMode {
    Auto,
    Always,
    Never,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum FileType {
    File,
    Directory,
    Symlink,
    BlockDevice,
    CharDevice,
    Executable,
    Empty,
    Socket,
    Pipe,
}

#[derive(Clone, Debug)]
pub enum Pattern {
    Regex(RegexMatcher),
    Glob(GlobMatcher),
}

#[derive(Clone, Debug)]
pub struct RegexMatcher {
    re: regex::Regex,
}

impl Pattern {
    pub fn matches(&self, candidate: &str) -> bool {
        match self {
            Pattern::Regex(m) => m.re.is_match(candidate),
            Pattern::Glob(g) => g.is_match(candidate),
        }
    }
}

/// A single search root.
#[derive(Clone, Debug)]
pub struct Root {
    /// The path exactly as it was given on the command line (empty for the implicit
    /// current-directory root).
    pub given: PathBuf,
    /// Whether this root is the implicit current working directory.
    pub is_cwd: bool,
    /// The path that is traversed.
    pub walk: PathBuf,
    /// The absolute path used for sorting, matching against the full path and building
    /// `file://` hyperlinks.
    pub abs: PathBuf,
    /// The canonicalized absolute path, used for `--absolute-path`.
    pub canon: PathBuf,
}

#[derive(Clone)]
pub struct Config {
    pub pattern: Option<Pattern>,
    pub and_patterns: Vec<Pattern>,
    pub roots: Vec<Root>,
    pub hidden: bool,
    pub ignore: bool,
    pub ignore_vcs: bool,
    pub require_git: bool,
    pub ignore_parent: bool,
    pub absolute_path: bool,
    pub list_details: bool,
    pub follow: bool,
    pub full_path: bool,
    pub print0: bool,
    pub max_depth: Option<usize>,
    pub min_depth: Option<usize>,
    pub excludes: Vec<globset::GlobMatcher>,
    pub prune: bool,
    pub types: Vec<FileType>,
    pub extensions: Vec<String>,
    pub sizes: Vec<SizeFilter>,
    pub changed_within: Option<TimeFilter>,
    pub changed_before: Option<TimeFilter>,
    pub owner: Option<OwnerFilter>,
    pub format: Option<String>,
    pub exec: Option<Vec<OsString>>,
    pub exec_batch: Option<Vec<OsString>>,
    pub batch_size: usize,
    pub ignore_files: Vec<PathBuf>,
    pub color: ColorMode,
    pub hyperlink: HyperlinkMode,
    pub ignore_contain: Vec<String>,
    pub threads: usize,
    pub max_results: usize,
    pub quiet: bool,
    pub show_errors: bool,
    pub path_separator: String,
    pub strip_cwd_prefix: StripMode,
    pub one_file_system: bool,
    pub ls_colors: LsColors,
    pub global_ignore_file: Option<PathBuf>,
    pub global_git_ignore: Option<PathBuf>,
    pub stdin_mode: bool,
}

pub fn compile_regex(pattern: &str, case_insensitive: bool) -> Result<RegexMatcher, FdError> {
    let builder = RegexBuilder::new(pattern).case_insensitive(case_insensitive);
    match builder.build() {
        Ok(re) => Ok(RegexMatcher { re }),
        Err(err) => Err(FdError::new(format!(
            "{}\n\nNote: You can use the '--fixed-strings' option to search for a literal \
             string instead of a regular expression. Alternatively, you can also use the \
             '--glob' option to match on a glob pattern.",
            err
        ))),
    }
}

pub fn compile_glob(pattern: &str, literal_separator: bool) -> Result<GlobMatcher, FdError> {
    let mut builder = GlobBuilder::new(pattern);
    if literal_separator {
        builder = builder.literal_separator(true);
    }
    match builder.build() {
        Ok(g) => Ok(g.compile_matcher()),
        Err(err) => Err(FdError::new(format!("error parsing glob '{}': {}", pattern, err))),
    }
}

pub fn build_config(cli: &Cli) -> Result<Config, FdError> {
    // --- case sensitivity ------------------------------------------------------------
    let case_insensitive = if cli.case_sensitive {
        false
    } else if cli.ignore_case {
        true
    } else {
        // Smart case: insensitive unless the pattern contains an uppercase character.
        !cli
            .pattern
            .as_deref()
            .map(|p| p.chars().any(|c| c.is_uppercase()))
            .unwrap_or(false)
    };

    let pattern = match &cli.pattern {
        None => None,
        Some(p) => {
            if cli.glob {
                Some(Pattern::Glob(compile_glob(p, cli.full_path)?))
            } else if cli.fixed_strings {
                let escaped = regex::escape(p);
                Some(Pattern::Regex(compile_regex(&escaped, case_insensitive)?))
            } else {
                Some(Pattern::Regex(compile_regex(p, case_insensitive)?))
            }
        }
    };

    let mut and_patterns = Vec::new();
    for p in &cli.and {
        let pat = if cli.glob {
            Pattern::Glob(compile_glob(p, cli.full_path)?)
        } else if cli.fixed_strings {
            Pattern::Regex(compile_regex(&regex::escape(p), case_insensitive)?)
        } else {
            Pattern::Regex(compile_regex(p, case_insensitive)?)
        };
        and_patterns.push(pat);
    }

    // --- types -----------------------------------------------------------------------
    let mut types = Vec::new();
    for t in &cli.types {
        let ft = match t.as_str() {
            "file" | "f" => FileType::File,
            "directory" | "d" | "dir" => FileType::Directory,
            "symlink" | "l" => FileType::Symlink,
            "block-device" | "b" => FileType::BlockDevice,
            "char-device" | "c" => FileType::CharDevice,
            "executable" | "x" => FileType::Executable,
            "empty" | "e" => FileType::Empty,
            "socket" | "s" => FileType::Socket,
            "pipe" | "p" => FileType::Pipe,
            _ => unreachable!(),
        };
        types.push(ft);
    }
    if types.iter().any(|t| *t == FileType::Executable) && !types.contains(&FileType::File) {
        types.push(FileType::File);
    }

    // --- extensions ------------------------------------------------------------------
    let extensions: Vec<String> = cli
        .extensions
        .iter()
        .map(|e| e.trim_start_matches('.').to_ascii_lowercase())
        .collect();

    // --- exclude patterns ------------------------------------------------------------
    let mut excludes = Vec::new();
    for pat in &cli.exclude {
        let clean = pat.strip_prefix('/').unwrap_or(pat);
        let matcher = match GlobBuilder::new(clean).build() {
            Ok(g) => g.compile_matcher(),
            Err(err) => {
                return Err(FdError::new(format!(
                    "Malformed exclude pattern: error parsing glob '!{}': {}",
                    pat, err
                )))
            }
        };
        excludes.push(matcher);
    }

    // --- time filters ----------------------------------------------------------------
    let changed_within = match &cli.changed_within {
        None => None,
        Some(v) => match parse_time(v) {
            Some(t) => Some(t),
            None => {
                return Err(FdError::new(format!(
                    "'{}' is not a valid date or duration. See 'fd --help'.",
                    v
                )))
            }
        },
    };
    let changed_before = match &cli.changed_before {
        None => None,
        Some(v) => match parse_time(v) {
            Some(mut t) => {
                t.before = true;
                Some(t)
            }
            None => {
                return Err(FdError::new(format!(
                    "'{}' is not a valid date or duration. See 'fd --help'.",
                    v
                )))
            }
        },
    };

    // --- owner filter ----------------------------------------------------------------
    let owner = match &cli.owner {
        None => None,
        Some(v) => Some(parse_owner(v).map_err(FdError::new)?),
    };

    // --- search roots ----------------------------------------------------------------
    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    let roots = build_roots(cli, &cwd);

    // --- colors ----------------------------------------------------------------------
    let color = match cli.color.as_str() {
        "always" => ColorMode::Always,
        "never" => ColorMode::Never,
        _ => ColorMode::Auto,
    };
    let hyperlink = match cli.hyperlink.as_deref() {
        None => HyperlinkMode::Never,
        Some("auto") => HyperlinkMode::Auto,
        Some("always") => HyperlinkMode::Always,
        _ => HyperlinkMode::Never,
    };
    let strip_cwd_prefix = match cli.strip_cwd_prefix.as_deref() {
        Some("always") => StripMode::Always,
        Some("never") => StripMode::Never,
        _ => StripMode::Auto,
    };
    let ls_colors = if let Ok(v) = std::env::var("LS_COLORS") {
        LsColors::from_env(&v)
    } else {
        default_ls_colors()
    };

    // --- ignore files ----------------------------------------------------------------
    let global_ignore_file = global_ignore_file_path();
    let global_git_ignore = global_git_ignore_path();

    let threads = cli.threads.unwrap_or_else(|| {
        std::thread::available_parallelism().map(|n| n.get()).unwrap_or(1)
    });

    let exec = if cli.exec.is_empty() { None } else { Some(cli.exec.clone()) };
    let exec_batch =
        if cli.exec_batch.is_empty() { None } else { Some(cli.exec_batch.clone()) };

    Ok(Config {
        pattern,
        and_patterns,
        roots,
        hidden: cli.hidden,
        ignore: cli.ignore,
        ignore_vcs: cli.ignore_vcs,
        require_git: cli.require_git,
        ignore_parent: cli.ignore_parent,
        absolute_path: cli.absolute_path,
        list_details: cli.list_details,
        follow: cli.follow,
        full_path: cli.full_path,
        print0: cli.print0,
        max_depth: cli.max_depth,
        min_depth: cli.min_depth,
        excludes,
        prune: cli.prune,
        types,
        extensions,
        sizes: cli.size.iter().filter_map(|s| parse_size(s)).collect(),
        changed_within,
        changed_before,
        owner,
        format: cli.format.clone(),
        exec,
        exec_batch,
        batch_size: cli.batch_size,
        ignore_files: cli.ignore_file.clone(),
        color,
        hyperlink,
        ignore_contain: cli.ignore_contain.clone(),
        threads,
        max_results: cli.max_results,
        quiet: cli.quiet,
        show_errors: cli.show_errors,
        path_separator: cli.path_separator.clone(),
        strip_cwd_prefix,
        one_file_system: cli.one_file_system,
        ls_colors,
        global_ignore_file,
        global_git_ignore,
        stdin_mode: false,
    })
}

fn build_roots(cli: &Cli, cwd: &Path) -> Vec<Root> {
    let cwd = cwd.to_path_buf();
    let given_paths: Vec<PathBuf> = if !cli.path.is_empty() {
        cli.path.clone()
    } else if !cli.search_path.is_empty() {
        cli.search_path.clone()
    } else {
        Vec::new()
    };
    if given_paths.is_empty() {
        let canon = std::fs::canonicalize(&cwd).unwrap_or_else(|_| cwd.clone());
        return vec![Root {
            given: PathBuf::new(),
            is_cwd: true,
            walk: cwd.clone(),
            abs: cwd.clone(),
            canon,
        }];
    }
    given_paths
        .iter()
        .map(|p| {
            let clean = crate::fshelper::strip_leading_cur_dir(p);
            let abs = if p.is_absolute() { p.clone() } else { cwd.join(clean) };
            let canon = std::fs::canonicalize(p).unwrap_or_else(|_| abs.clone());
            Root {
                given: p.clone(),
                is_cwd: false,
                walk: p.clone(),
                abs,
                canon,
            }
        })
        .collect()
}

/// `$HOME/.config/fd/ignore` (or the equivalent on this platform).
fn global_ignore_file_path() -> Option<PathBuf> {
    if let Ok(home) = std::env::var("HOME") {
        let p = PathBuf::from(&home).join(".config/fd/ignore");
        if p.exists() {
            return Some(p);
        }
    }
    None
}

fn global_git_ignore_path() -> Option<PathBuf> {
    // core.excludesFile, which defaults to $HOME/.config/git/ignore
    let mut candidate = None;
    if let Ok(home) = std::env::var("HOME") {
        candidate = Some(PathBuf::from(&home).join(".config/git/ignore"));
    }
    if let Ok(xdg) = std::env::var("XDG_CONFIG_HOME") {
        candidate = Some(PathBuf::from(&xdg).join("git/ignore"));
    }
    let p = candidate?;
    if p.exists() { Some(p) } else { None }
}

impl Config {
    /// Whether the traversal/output runs in a streaming fashion (no sorting of results).
    pub fn is_streaming(&self) -> bool {
        self.quiet || self.exec.is_some() || self.exec_batch.is_some() || self.max_results != 0
    }

    /// Whether the `./` prefix should be added to relative paths of the cwd root.
    pub fn add_cwd_prefix(&self) -> bool {
        match self.strip_cwd_prefix {
            StripMode::Never => true,
            StripMode::Always => false,
            StripMode::Auto => {
                self.print0 || self.exec.is_some() || self.exec_batch.is_some()
            }
        }
    }

    pub fn style_for_indicator(&self, ind: Indicator) -> Option<&Style> {
        self.ls_colors.style_for(ind)
    }
}
RSEOF
echo ok; wc -l src/config.rs"}

