        let clean = pat.strip_prefix('/').unwrap_or(pat);
        let matcher = match GlobBuilder::new(clean).build() {
            Ok(g) => g.compile_matcher(),
            Err(err) => {
                return Err(FdError::new(format!(
                    "Malformed exclude pattern: error parsing glob '!{}': {}",
                    pat, err
                )))
            }
        };
        excludes.push(matcher);
    }

    // --- time filters ----------------------------------------------------------------
    let changed_within = match &cli.changed_within {
        None => None,
        Some(v) => match parse_time(v) {
            Some(t) => Some(t),
            None => {
                return Err(FdError::new(format!(
                    "'{}' is not a valid date or duration. See 'fd --help'.",
                    v
                )))
            }
        },
    };
    let changed_before = match &cli.changed_before {
        None => None,
        Some(v) => match parse_time(v) {
            Some(mut t) => {
                t.before = true;
                Some(t)
            }
            None => {
                return Err(FdError::new(format!(
                    "'{}' is not a valid date or duration. See 'fd --help'.",
                    v
                )))
            }
        },
    };

    // --- owner filter ----------------------------------------------------------------
    let owner = match &cli.owner {
        None => None,
        Some(v) => Some(parse_owner(v).map_err(FdError::new)?),
    };

    // --- search roots ----------------------------------------------------------------
    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    let roots = build_roots(cli, &cwd);

    // --- colors ----------------------------------------------------------------------
    let color = match cli.color.as_str() {
        "always" => ColorMode::Always,
        "never" => ColorMode::Never,
        _ => ColorMode::Auto,
    };
    let hyperlink = match cli.hyperlink.as_deref() {
        None => HyperlinkMode::Never,
        Some("auto") => HyperlinkMode::Auto,
        Some("always") => HyperlinkMode::Always,
        _ => HyperlinkMode::Never,
    };
    let strip_cwd_prefix = match cli.strip_cwd_prefix.as_deref() {
        Some("always") => StripMode::Always,
        Some("never") => StripMode::Never,
        _ => StripMode::Auto,
    };
    let ls_colors = if let Ok(v) = std::env::var("LS_COLORS") {
        LsColors::from_env(&v)
    } else {
        default_ls_colors()
    };

    // --- ignore files ----------------------------------------------------------------
    let global_ignore_file = global_ignore_file_path();
    let global_git_ignore = global_git_ignore_path();

    let threads = cli.threads.unwrap_or_else(|| {
        std::thread::available_parallelism().map(|n| n.get()).unwrap_or(1)
    });

    let exec = if cli.exec.is_empty() { None } else { Some(cli.exec.clone()) };
    let exec_batch =
        if cli.exec_batch.is_empty() { None } else { Some(cli.exec_batch.clone()) };

    Ok(Config {
        pattern,
        and_patterns,
        roots,
        hidden: cli.hidden,
        ignore: cli.ignore,
        ignore_vcs: cli.ignore_vcs,
        require_git: cli.require_git,
        ignore_parent: cli.ignore_parent,
        absolute_path: cli.absolute_path,
