        ls_colors,
        global_ignore_file,
        global_git_ignore,
        stdin_mode: false,
    })
}

fn build_roots(cli: &Cli, cwd: &Path) -> Vec<Root> {
    let cwd = cwd.to_path_buf();
    let given_paths: Vec<PathBuf> = if !cli.path.is_empty() {
        cli.path.clone()
    } else if !cli.search_path.is_empty() {
        cli.search_path.clone()
    } else {
        Vec::new()
    };
    if given_paths.is_empty() {
        let canon = std::fs::canonicalize(&cwd).unwrap_or_else(|_| cwd.clone());
        return vec![Root {
            given: PathBuf::new(),
            is_cwd: true,
            walk: cwd.clone(),
            abs: cwd.clone(),
            canon,
        }];
    }
    given_paths
        .iter()
        .map(|p| {
            let clean = crate::fshelper::strip_leading_cur_dir(p);
            let abs = if p.is_absolute() { p.clone() } else { cwd.join(clean) };
            let canon = std::fs::canonicalize(p).unwrap_or_else(|_| abs.clone());
            Root {
                given: p.clone(),
                is_cwd: false,
                walk: p.clone(),
                abs,
                canon,
            }
        })
        .collect()
}

/// `$HOME/.config/fd/ignore` (or the equivalent on this platform).
fn global_ignore_file_path() -> Option<PathBuf> {
    if let Ok(home) = std::env::var("HOME") {
        let p = PathBuf::from(&home).join(".config/fd/ignore");
        if p.exists() {
            return Some(p);
        }
    }
    None
}

fn global_git_ignore_path() -> Option<PathBuf> {
    // core.excludesFile, which defaults to $HOME/.config/git/ignore
    let mut candidate = None;
    if let Ok(home) = std::env::var("HOME") {
        candidate = Some(PathBuf::from(&home).join(".config/git/ignore"));
    }
    if let Ok(xdg) = std::env::var("XDG_CONFIG_HOME") {
        candidate = Some(PathBuf::from(&xdg).join("git/ignore"));
    }
    let p = candidate?;
    if p.exists() { Some(p) } else { None }
}

impl Config {
    /// Whether the traversal/output runs in a streaming fashion (no sorting of results).
    pub fn is_streaming(&self) -> bool {
        self.quiet || self.exec.is_some() || self.exec_batch.is_some() || self.max_results != 0
    }

    /// Whether the `./` prefix should be added to relative paths of the cwd root.
    pub fn add_cwd_prefix(&self) -> bool {
        match self.strip_cwd_prefix {
            StripMode::Never => true,
            StripMode::Always => false,
            StripMode::Auto => {
                self.print0 || self.exec.is_some() || self.exec_batch.is_some()
            }
        }
    }

    pub fn style_for_indicator(&self, ind: Indicator) -> Option<&Style> {
        self.ls_colors.style_for(ind)
    }
}
