pub fn compile_regex(pattern: &str, case_insensitive: bool) -> Result<RegexMatcher, FdError> {
    let builder = RegexBuilder::new(pattern).case_insensitive(case_insensitive);
    match builder.build() {
        Ok(re) => Ok(RegexMatcher { re }),
        Err(err) => Err(FdError::new(format!(
            "{}\n\nNote: You can use the '--fixed-strings' option to search for a literal \
             string instead of a regular expression. Alternatively, you can also use the \
             '--glob' option to match on a glob pattern.",
            err
