    }
}

pub fn compile_glob(pattern: &str, literal_separator: bool) -> Result<GlobMatcher, FdError> {
    let mut builder = GlobBuilder::new(pattern);
    if literal_separator {
        builder = builder.literal_separator(true);
    }
    match builder.build() {
        Ok(g) => Ok(g.compile_matcher()),
        Err(err) => Err(FdError::new(format!("error parsing glob '{}': {}", pattern, err))),
    }
