        if self.config.absolute_path {
            return root.canon.join(&entry.rel);
        }
        if root.is_cwd {
            if self.config.add_cwd_prefix() {
                return PathBuf::from("./").join(&entry.rel);
            }
            return entry.rel.clone();
        }
        root.given.join(&entry.rel)
    }

    /// The absolute path used for sorting, full path matching and hyperlinks.
    pub fn absolute_path(&self, entry: &DirEntry) -> PathBuf {
        let root = &self.config.roots[entry.root];
        root.abs.join(&entry.rel)
    }

    /// The style used to print the last path component of this entry.
    pub fn style_for(&self, entry: &DirEntry) -> Option<Style> {
        if !self.use_color {
            return None;
        }
        let ls = &self.config.ls_colors;
        let md = entry.metadata.as_ref();
        let style = if entry.is_symlink {
            if entry.link_target_exists {
                ls.style_for(Indicator::SymbolicLink)
            } else {
                ls.style_for(Indicator::BrokenSymbolicLink)
                    .or_else(|| ls.style_for(Indicator::SymbolicLink))
            }
        } else if entry.is_dir {
            let (sticky, other_writable) = match md {
                Some(m) => (
                    m.mode() & 0o1000 != 0,
                    m.mode() & 0o0002 != 0,
                ),
                None => (false, false),
            };
            if sticky && other_writable {
                ls.style_for(Indicator::StickyOtherWritable)
            } else if other_writable {
                ls.style_for(Indicator::OtherWritable)
            } else if sticky {
                ls.style_for(Indicator::Sticky)
            } else {
                ls.style_for(Indicator::Directory)
            }
        } else if let Some(m) = md {
            if m.mode() & 0o4000 != 0 {
                ls.style_for(Indicator::Setuid)
            } else if m.mode() & 0o2000 != 0 {
                ls.style_for(Indicator::Setgid)
            } else {
                match file_kind(m) {
                    crate::dir_entry::Kind::Socket => ls.style_for(Indicator::Socket),
                    crate::dir_entry::Kind::Fifo => ls.style_for(Indicator::Fifo),
                    crate::dir_entry::Kind::CharDevice => ls.style_for(Indicator::CharDevice),
                    crate::dir_entry::Kind::BlockDevice => ls.style_for(Indicator::BlockDevice),
                    crate::dir_entry::Kind::Door => ls.style_for(Indicator::Door),
                    crate::dir_entry::Kind::Other => {
                        if entry.is_executable() {
                            ls.style_for(Indicator::ExecutableFile)
                        } else {
                            ls.style_for_file_name(&entry.file_name())
                                .or_else(|| ls.style_for(Indicator::RegularFile))
                        }
                    }
                }
            }
        } else {
            None
        };
        style.cloned()
    }

    /// Write a single entry (without a trailing newline).
    pub fn write_entry(&mut self, entry: &DirEntry) -> io::Result<()> {
        if let Some(fmt) = &self.config.format {
            let path = self.display_path(entry);
            let line = crate::format::expand(
                fmt,
                &crate::format::Placeholders::new(&path, entry.is_dir, &self.separator),
            );
            self.out.write_all(line.as_bytes())?;
            if self.config.print0 {
                self.out.write_all(b"\0")?;
            } else {
                self.out.write_all(b"\n")?;
            }
            return Ok(());
        }

        let mut path = self.display_path(entry);
        let is_dir = entry.is_dir && !self.config.list_details;
        let sep = self.separator.clone();
        let url = if self.use_hyperlink {
            Some(crate::fshelper::url_encode(&self.absolute_path(entry)))
        } else {
            None
        };

        // Build the output.
        let path_str = path.to_string_lossy().to_string();
        let components: Vec<&str> = if self.config.absolute_path {
            path_str.split('/').collect()
        } else {
            path_str.split('/').collect()
        };
        let _ = &components;

        if self.use_color {
            let dir_style = self
                .config
                .style_for_indicator(Indicator::Directory)
                .map(|s| s.to_ansi())
                .unwrap_or_default();
            let entry_style = self
                .style_for(entry)
                .map(|s| s.to_ansi())
                .unwrap_or_default();

            // hyperlink start
            if let Some(u) = &url {
                self.out.write_all(format!("\x1b]8;;file://{}{}\x1b\\", crate::fshelper::hostname(), u).as_bytes())?;
            }
            // All but the last component, joined with the separator.
            if components.len() > 1 {
                let mut prefix = String::new();
                for (i, c) in components.iter().enumerate() {
                    if i + 1 == components.len() {
                        break;
                    }
                    prefix.push_str(c);
                    prefix.push_str(&sep);
                }
                if !dir_style.is_empty() {
                    self.out.write_all(dir_style.as_bytes())?;
                    self.out.write_all(prefix.as_bytes())?;
                    self.out.write_all(b"\x1b[0m")?;
                } else {
                    self.out.write_all(prefix.as_bytes())?;
                }
            }
            // The last component.
            if !entry_style.is_empty() {
                self.out.write_all(entry_style.as_bytes())?;
                let last = components.last().copied().unwrap_or("");
                self.out.write_all(last.as_bytes())?;
                self.out.write_all(b"\x1b[0m")?;
            } else {
                let last = components.last().copied().unwrap_or("");
                self.out.write_all(last.as_bytes())?;
            }
            // Trailing separator for directories.
            if is_dir && !dir_style.is_empty() {
                self.out.write_all(dir_style.as_bytes())?;
                self.out.write_all(sep.as_bytes())?;
                self.out.write_all(b"\x1b[0m")?;
            } else if is_dir {
                self.out.write_all(sep.as_bytes())?;
            }
            if url.is_some() {
                self.out.write_all(b"\x1b]8;;\x1b\\")?;
            }
        } else {
            if let Some(u) = &url {
                self.out.write_all(format!("\x1b]8;;file://{}{}\x1b\\", crate::fshelper::hostname(), u).as_bytes())?;
            }
            if components.len() > 1 {
                let mut prefix = String::new();
                for (i, c) in components.iter().enumerate() {
                    if i + 1 == components.len() {
                        break;
                    }
                    prefix.push_str(c);
                    prefix.push_str(&sep);
                }
                self.out.write_all(prefix.as_bytes())?;
            }
            let last = components.last().copied().unwrap_or("");
            self.out.write_all(last.as_bytes())?;
            if is_dir {
                self.out.write_all(sep.as_bytes())?;
            }
            if url.is_some() {
                self.out.write_all(b"\x1b]8;;\x1b\\")?;
            }
        }
        let _ = &mut path;
        Ok(())
    }

    pub fn flush(&mut self) -> io::Result<()> {
        self.out.flush()
    }
}

/// The kind of a file, derived from its metadata.
pub fn file_kind(m: &std::fs::Metadata) -> crate::dir_entry::Kind {
    use std::os::unix::fs::FileTypeExt;
    let ft = m.file_type();
    if ft.is_socket() {
        crate::dir_entry::Kind::Socket
    } else if ft.is_fifo() {
        crate::dir_entry::Kind::Fifo
    } else if ft.is_char_device() {
        crate::dir_entry::Kind::CharDevice
    } else if ft.is_block_device() {
        crate::dir_entry::Kind::BlockDevice
    } else {
        crate::dir_entry::Kind::Other
    }
}

fn is_stdout_terminal() -> bool {
    unsafe { libc::isatty(libc::STDOUT_FILENO) == 1 }
}
