//! Expansion of `--format` and `--exec` placeholders.

use std::path::Path;

pub struct Placeholders<'a> {
    pub path: String,
    pub is_dir: bool,
    pub separator: &'a str,
}

impl<'a> Placeholders<'a> {
    pub fn new(path: &Path, is_dir: bool, separator: &'a str) -> Placeholders<'a> {
        let path = path.to_string_lossy().replace('/', separator);
        Placeholders { path, is_dir, separator }
    }
}

/// Expand the placeholders in `template`.
pub fn expand(template: &str, ph: &Placeholders) -> String {
    let bytes: Vec<char> = template.chars().collect();
    let mut out = String::new();
    let mut i = 0usize;
    while i < bytes.len() {
        if bytes[i] != '{' && bytes[i] != '}' {
            out.push(bytes[i]);
            i += 1;
            continue;
        }
        // Try to match a placeholder starting at `i`.
        if let Some((len, value)) = match_placeholder(&bytes[i..], ph) {
            out.push_str(&value);
            i += len;
        } else {
            out.push(bytes[i]);
            i += 1;
        }
    }
    out
}

fn match_placeholder(rest: &[char], ph: &Placeholders) -> Option<(usize, String)> {
    let starts: &[(&str, &str)] = &[
        ("{", "{"),
        ("}", "}"),
    ];
    // Escapes first: `{{` and `}}`
    if rest.len() >= 2 && rest[0] == '{' && rest[1] == '{' {
        return Some((2, "{".to_string()));
    }
    if rest.len() >= 2 && rest[0] == '}' && rest[1] == '}' {
        return Some((2, "}".to_string()));
    }
    if rest[0] != '{' {
        return None;
    }
    const PLACEHOLDERS: &[(&str, PlaceholderKind)] = &[
        ("{/.}", PlaceholderKind::BasenameNoExt),
        ("{//}", PlaceholderKind::Parent),
        ("{/}", PlaceholderKind::Basename),
        ("{.}", PlaceholderKind::NoExt),
        ("{}", PlaceholderKind::Path),
    ];
    for (pat, kind) in PLACEHOLDERS {
        let chars: Vec<char> = pat.chars().collect();
        if rest.len() >= chars.len() && rest[..chars.len()] == chars[..] {
            return Some((chars.len(), value_for(*kind, ph)));
        }
    }
    let _ = starts;
    None
}

#[derive(Clone, Copy)]
enum PlaceholderKind {
    Path,
    Basename,
    Parent,
    NoExt,
    BasenameNoExt,
}

fn value_for(kind: PlaceholderKind, ph: &Placeholders) -> String {
    let sep = ph.separator;
    let path = &ph.path;
    match kind {
        PlaceholderKind::Path => path.clone(),
        PlaceholderKind::Basename => {
            let base = Path::new(path)
                .file_name()
                .map(|n| n.to_string_lossy().to_string())
                .unwrap_or_else(|| path.clone());
            if ph.is_dir && !base.is_empty() {
                base
            } else {
                base
            }
        }
        PlaceholderKind::Parent => {
            let p = Path::new(path);
            match p.parent() {
                Some(par) => {
                    if par.as_os_str().is_empty() {
                        ".".to_string()
                    } else {
                        par.to_string_lossy().replace('/', sep)
                    }
                }
                None => ".".to_string(),
            }
        }
        PlaceholderKind::NoExt => {
            let p = Path::new(path);
            match p.to_str().and_then(|s| strip_ext(s)) {
                Some(s) => s,
                None => path.clone(),
            }
        }
        PlaceholderKind::BasenameNoExt => {
            let p = Path::new(path);
            let base = p
                .file_name()
                .map(|n| n.to_string_lossy().to_string())
                .unwrap_or_else(|| path.clone());
            strip_ext(&base).unwrap_or(base)
        }
    }
}

/// Remove the last extension from a path string (the part after the final `.` of the
/// file name), if any.
fn strip_ext(s: &str) -> Option<String> {
    let path = Path::new(s);
    let stem = path.file_stem()?.to_string_lossy().to_string();
    match path.parent() {
        Some(par) if !par.as_os_str().is_empty() => Some(par.join(stem).to_string_lossy().to_string()),
        Some(_) => Some(stem),
        None => Some(stem),
    }
}
