//! Parallel and batched command execution.

use crate::dir_entry::DirEntry;
use crate::format::expand;
use crate::format::Placeholders;
use std::ffi::OsString;
use std::os::unix::process::ExitStatusExt;
use std::path::Path;
use std::process::Command;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;

/// Expand the placeholders for a single search result.
pub fn expand_for_entry(
    cmd: &[OsString],
    path: &Path,
    is_dir: bool,
    separator: &str,
) -> Vec<OsString> {
    let ph = Placeholders::new(path, is_dir, separator);
    let mut out = Vec::with_capacity(cmd.len());
    for arg in cmd {
        let s = arg.to_string_lossy().to_string();
        if contains_placeholder(&s) {
            out.push(OsString::from(expand(&s, &ph)));
        } else {
            out.push(arg.clone());
        }
    }
    out
}

/// Expand the placeholders for a batch of search results. Placeholders expand to
/// *several* arguments (one per result).
pub fn expand_for_batch(
    cmd: &[OsString],
    entries: &[(PathBufLike, bool)],
    separator: &str,
) -> Vec<OsString> {
    let mut out = Vec::new();
    for arg in cmd {
        let s = arg.to_string_lossy().to_string();
        if !contains_placeholder(&s) {
            out.push(arg.clone());
            continue;
        }
        // Expand the placeholders, producing one argument per result.
        let mut any_expanded = false;
        for (path, is_dir) in entries {
            let ph = Placeholders::new(path, *is_dir, separator);
            let expanded = expand(&s, &ph);
            out.push(OsString::from(expanded));
            any_expanded = true;
        }
        if !any_expanded {
            out.push(arg.clone());
        }
    }
    if out.is_empty() {
        // Implicit "{}"
        for (path, _) in entries {
            out.push(OsString::from(path.to_string_lossy().replace('/', separator)));
        }
    }
    out
}

pub type PathBufLike = std::path::PathBuf;

fn contains_placeholder(s: &str) -> bool {
    s.contains('{') || s.contains('}')
}

/// Run the given command, returning `true` when it succeeded.
pub fn run_command(cmd: &[OsString], errors: &AtomicBool) -> bool {
    if cmd.is_empty() {
        return true;
    }
    match Command::new(&cmd[0]).args(&cmd[1..]).spawn() {
        Ok(mut child) => match child.wait() {
            Ok(status) => {
                if status.success() {
                    true
                } else {
                    errors.store(true, Ordering::SeqCst);
                    false
                }
            }
            Err(_) => {
                eprintln!("[fd error]: Command not found: {}", cmd[0].to_string_lossy());
                errors.store(true, Ordering::SeqCst);
                false
            }
        },
        Err(_) => {
            eprintln!("[fd error]: Command not found: {}", cmd[0].to_string_lossy());
            errors.store(true, Ordering::SeqCst);
            false
        }
    }
}

/// The maximum number of bytes that can be passed on the command line.
pub fn arg_max() -> usize {
    let mut size: libc::c_long = unsafe { libc::sysconf(libc::_SC_ARG_MAX) };
    if size <= 0 {
        size = 4096 * 1024;
    }
    // Leave room for the environment and some slack.
    let env_size: usize = std::env::vars_os().map(|(k, v)| k.len() + v.len() + 2).sum();
    let max = size as usize;
    if env_size + 2048 >= max {
        4096
    } else {
        max - env_size - 2048
    }
}

/// Exit code for a terminated child, mirroring `ExitStatus::into_raw`.
pub fn exit_code(status: std::process::ExitStatus) -> i32 {
    status.into_raw()
}

pub fn had_error(errors: &Arc<AtomicBool>) -> bool {
    errors.load(Ordering::SeqCst)
}
