// ---------------------------------------------------------------------------
// Entry filtering
// ---------------------------------------------------------------------------

use crate::config::{Config, FileType};

/// The information about an entry needed to apply the filters.
pub struct EntryInfo<'a> {
    pub file_name: &'a str,
    pub full_path: &'a Path,
    pub is_dir: bool,
    pub is_symlink: bool,
    pub metadata: Option<&'a std::fs::Metadata>,
}

impl<'a> EntryInfo<'a> {
    pub fn kind_matches(&self, ft: FileType) -> bool {
        match ft {
            FileType::File => !self.is_dir && !self.is_symlink,
            FileType::Directory => self.is_dir,
            FileType::Symlink => self.is_symlink,
            FileType::BlockDevice => self
                .metadata
                .map(|m| m.file_type().is_block_device())
                .unwrap_or(false),
            FileType::CharDevice => self
                .metadata
                .map(|m| m.file_type().is_char_device())
                .unwrap_or(false),
            FileType::Executable => self
                .metadata
                .map(|m| !m.is_dir() && m.mode() & 0o111 != 0)
                .unwrap_or(false),
            FileType::Socket => self
                .metadata
                .map(|m| m.file_type().is_socket())
                .unwrap_or(false),
            FileType::Pipe => self
                .metadata
                .map(|m| m.file_type().is_fifo())
                .unwrap_or(false),
            FileType::Empty => match self.metadata {
                Some(m) => {
                    if m.is_dir() {
                        crate::dir_entry::dir_is_empty(Path::new(self.full_path))
                    } else {
                        m.len() == 0
                    }
                }
                None => false,
            },
        }
    }

    pub fn extension_matches(&self, extensions: &[String]) -> bool {
        if extensions.is_empty() {
            return true;
        }
        match crate::fshelper::extension(self.file_name) {
            Some(e) => extensions.iter().any(|x| x == &e.to_ascii_lowercase()),
            None => false,
        }
    }

    pub fn size_matches(&self, filters: &[crate::filters::SizeFilter]) -> bool {
        if filters.is_empty() {
            return true;
        }
        if self.is_dir {
            return false;
        }
        match self.metadata.map(|m| m.len()) {
            Some(size) => filters.iter().all(|f| f.matches(size)),
            None => false,
        }
    }

    pub fn time_matches(
        &self,
        within: &Option<crate::filters::TimeFilter>,
        before: &Option<crate::filters::TimeFilter>,
    ) -> bool {
        if within.is_none() && before.is_none() {
            return true;
        }
        let mtime = match self.metadata.and_then(|m| m.modified().ok()) {
            Some(t) => t,
            None => return false,
        };
        if let Some(f) = within {
            if !f.matches(mtime) {
                return false;
            }
        }
        if let Some(f) = before {
            if !f.matches(mtime) {
                return false;
            }
        }
        true
    }

    pub fn owner_matches(&self, owner: &Option<crate::filters::OwnerFilter>) -> bool {
        match owner {
            None => true,
            Some(f) => match self.metadata {
                Some(m) => f.matches(m.uid(), m.gid()),
                None => false,
            },
        }
    }
}

/// Check the pattern against this entry.
pub fn pattern_matches(config: &Config, info: &EntryInfo) -> bool {
    let candidate = if config.full_path {
        info.full_path.to_string_lossy().to_string()
    } else {
        info.file_name.to_string()
    };
    let main_ok = match &config.pattern {
        None => true,
        Some(p) => p.matches(&candidate),
    };
    if !main_ok {
        return false;
    }
    config.and_patterns.iter().all(|p| p.matches(&candidate))
}

/// Whether the entry passes all the output filters.
pub fn entry_matches(config: &Config, info: &EntryInfo) -> bool {
    if !pattern_matches(config, info) {
        return false;
    }
    if !config.types.is_empty() && !config.types.iter().any(|t| info.kind_matches(*t)) {
        return false;
    }
    if !info.extension_matches(&config.extensions) {
        return false;
    }
    if !info.size_matches(&config.sizes) {
        return false;
    }
    if !info.time_matches(&config.changed_within, &config.changed_before) {
        return false;
    }
    if !info.owner_matches(&config.owner) {
        return false;
    }
    true
}
