//! The filesystem walker.

use crate::config::Config;
use crate::dir_entry::DirEntry;
use ignore::{DirEntry as IgnoreEntry, Error as IgnoreError, WalkBuilder, WalkState};
use std::fs;
use std::path::PathBuf;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::mpsc::Sender;
use std::sync::Arc;

pub struct Walker<'a> {
    pub config: &'a Config,
    pub errors: Arc<AtomicBool>,
    pub had_ignore_errors: Arc<AtomicBool>,
}

impl<'a> Walker<'a> {
    pub fn new(config: &'a Config) -> Walker<'a> {
        Walker {
            config,
            errors: Arc::new(AtomicBool::new(false)),
            had_ignore_errors: Arc::new(AtomicBool::new(false)),
        }
    }

    /// Walk all the search roots, sending each entry to `send`. Returning `false` from
    /// `send` stops the traversal.
    pub fn walk(&self, send: &mut dyn FnMut(DirEntry) -> bool) {
        let config = self.config;
        let (tx, rx) = std::sync::mpsc::channel::<DirEntry>();
        let threads = config.threads.max(1);
        let stop = Arc::new(AtomicBool::new(false));

        let mut builder = WalkBuilder::new(&config.roots[0].walk);
        for root in &config.roots[1..] {
            builder.add(&root.walk);
        }
        builder
            .hidden(config.hidden)
            .ignore(config.ignore)
            .git_ignore(config.ignore_vcs)
            .git_global(config.ignore_vcs)
            .git_exclude(config.ignore_vcs)
            .require_git(config.require_git)
            .parents(config.ignore_parent)
            .follow_links(config.follow)
            .same_file_system(config.one_file_system)
            .threads(threads)
            .max_depth(config.max_depth)
            .min_depth(config.min_depth);

        if config.ignore {
            builder.add_custom_ignore_filename(".fdignore");
            if let Some(g) = &config.global_ignore_file {
                builder.add_ignore(g);
            }
        }
        for f in &config.ignore_files {
            builder.add_ignore(f);
        }

        let excludes = config.excludes.clone();
        let ignore_contain = config.ignore_contain.clone();
        let prune = config.prune;
        let show_errors = config.show_errors;
        let cfg = config.clone();
        builder.filter_entry(move |entry: &IgnoreEntry| -> bool {
            let ft = entry.file_type();
            let is_dir = ft.map(|t| t.is_dir()).unwrap_or(false);
            if is_dir && !ignore_contain.is_empty() {
                for name in &ignore_contain {
                    if entry.path().join(name).exists() {
                        return false;
                    }
                }
            }
            if !excludes.is_empty() {
                let rel = crate::fshelper::rel_path(entry.path());
                for g in &excludes {
                    if g.is_match(&rel) {
                        return false;
                    }
                }
            }
            if prune && is_dir {
                let info = crate::filters::EntryInfo {
                    file_name: &entry.file_name().to_string_lossy(),
                    full_path: &crate::fshelper::abs_of(&cfg, entry.path()),
                    is_dir,
                    is_symlink: ft.map(|t| t.is_symlink()).unwrap_or(false),
                    metadata: entry.metadata().ok().as_ref(),
                };
                if crate::filters::entry_matches(&cfg, &info) {
                    return false;
                }
            }
            true
        });

        let stop_c = stop.clone();
        let err_c = self.errors.clone();
        builder.build_parallel().run(move || {
            let tx = tx.clone();
            let stop = stop_c.clone();
            let errors = err_c.clone();
            let cfg = config.clone();
            Box::new(move |result: Result<IgnoreEntry, IgnoreError>| -> WalkState {
                if stop.load(Ordering::SeqCst) {
                    return WalkState::Quit;
                }
                match result {
                    Ok(dent) => {
                        if dent.depth() == 0 {
                            return WalkState::Continue;
                        }
                        match make_entry(&cfg, &dent) {
                            Some(entry) => {
                                let info = crate::filters::EntryInfo {
                                    file_name: &entry.file_name(),
                                    full_path: &entry.full_path,
                                    is_dir: entry.is_dir,
                                    is_symlink: entry.is_symlink,
                                    metadata: entry.metadata.as_ref(),
                                };
                                if crate::filters::entry_matches(&cfg, &info) {
                                    if tx.send(entry).is_err() || !stop.load(Ordering::SeqCst) {
                                        if tx.send(crate::dir_entry::DirEntry::dummy()).is_err() {
                                            return WalkState::Quit;
                                        }
                                    }
                                }
                                WalkState::Continue
                            }
                            None => WalkState::Continue,
                        }
                    }
                    Err(err) => {
                        if show_errors {
                            match err.path() {
                                Some(p) => eprintln!("[fd error]: {}: {}", p.display(), err),
                                None => eprintln!("[fd error]: {}", err),
                            }
                        }
                        WalkState::Continue
                    }
                }
            }) as Box<dyn FnMut(Result<IgnoreEntry, IgnoreError>) -> WalkState + Send>
        });
        let _ = &errors;
        drop(tx);
        // Drain the receiver through the caller-provided callback.
        for entry in rx {
            if !send(entry) {
                stop.store(true, Ordering::SeqCst);
                break;
            }
        }
    }
}
