//! The directory entries produced by the walker.

use std::fs;
use std::os::unix::fs::MetadataExt;
use std::path::PathBuf;
use std::time::SystemTime;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Kind {
    Socket,
    Fifo,
    CharDevice,
    BlockDevice,
    Door,
    Other,
}

#[derive(Clone, Debug)]
pub struct DirEntry {
    /// Index into `Config::roots`.
    pub root: usize,
    /// Path relative to the search root.
    pub rel: PathBuf,
    /// Absolute path (used for sorting, full-path matching and hyperlinks).
    pub full_path: PathBuf,
    /// Depth below the root (0 for the root itself).
    pub depth: usize,
    pub is_dir: bool,
    pub is_symlink: bool,
    pub metadata: Option<fs::Metadata>,
    /// Whether the target of a symlink exists.
    pub link_target_exists: bool,
}

impl DirEntry {
    pub fn file_name(&self) -> String {
        match self.rel.file_name() {
            Some(n) => n.to_string_lossy().to_string(),
            None => self.rel.to_string_lossy().to_string(),
        }
    }

    pub fn is_executable(&self) -> bool {
        if self.is_dir {
            return false;
        }
        self.metadata
            .as_ref()
            .map(|m| m.mode() & 0o111 != 0)
            .unwrap_or(false)
    }

    pub fn size(&self) -> Option<u64> {
        self.metadata.as_ref().map(|m| m.len())
    }

    pub fn modified(&self) -> Option<SystemTime> {
        self.metadata.as_ref().and_then(|m| m.modified().ok())
    }

    pub fn uid(&self) -> Option<u32> {
        self.metadata.as_ref().map(|m| m.uid())
    }

    pub fn gid(&self) -> Option<u32> {
        self.metadata.as_ref().map(|m| m.gid())
    }
}

/// Determine whether a directory is empty.
pub fn dir_is_empty(path: &std::path::Path) -> bool {
    match fs::read_dir(path) {
        Ok(mut rd) => rd.next().is_none(),
        Err(_) => false,
    }
}

/// The kind of a file, derived from its metadata.
pub fn file_kind(m: &fs::Metadata) -> Kind {
    use std::os::unix::fs::FileTypeExt;
    let ft = m.file_type();
    if ft.is_socket() {
        Kind::Socket
    } else if ft.is_fifo() {
        Kind::Fifo
    } else if ft.is_char_device() {
        Kind::CharDevice
    } else if ft.is_block_device() {
        Kind::BlockDevice
    } else {
        Kind::Other
    }
}
