/// The path relative to the search root (used for exclude pattern matching).
pub fn rel_path(path: &Path) -> PathBuf {
    path.to_path_buf()
}

/// The path relative to the given root.
pub fn rel_of(config: &crate::config::Config, root_idx: usize, path: &Path) -> PathBuf {
    let root = &config.roots[root_idx];
    match path.strip_prefix(&root.walk) {
        Ok(rel) => rel.to_path_buf(),
        Err(_) => path.to_path_buf(),
    }
}

/// The absolute path of an entry (used for sorting, matching and hyperlinks).
pub fn abs_of(config: &crate::config::Config, path: &Path) -> PathBuf {
    if path.is_absolute() {
        return path.to_path_buf();
    }
    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    to_absolute(&cwd, path)
}
