            if total > argmax && i > idx {
                batch_end = i;
                break;
            }
        }
        let slice: Vec<(PathBuf, bool)> = entries[idx..batch_end].to_vec();
        let args = crate::exec::expand_for_batch(cmd, &slice, &config.path_separator);
        crate::exec::run_command(&args, &errors);
        idx = batch_end;
        if batch_end == idx && idx < entries.len() {
            break;
        }
    }
    Ok(if crate::exec::had_error(&errors) || had_error() { 1 } else { 0 })
}

fn display_path(config: &Config, entry: &DirEntry) -> PathBuf {
    let root = &config.roots[entry.root];
    if config.absolute_path {
        return root.canon.join(&entry.rel);
    }
    if root.is_cwd {
        if config.add_cwd_prefix() {
            return PathBuf::from("./").join(&entry.rel);
        }
        return entry.rel.clone();
    }
    root.given.join(&entry.rel)
}

